import { showApplePay } from '../payments'

/** The cart total, with Apple Pay when the browser offers it. */
export function CartSummary({ items = [] }: { items?: { name: string; price: number }[] }) {
  const total = items.reduce((sum, item) => sum + item.price, 0)
  return (
    <aside>
      Total: ${total.toFixed(2)}
      {showApplePay() && <button className="apple-pay">Pay with Apple Pay</button>}
    </aside>
  )
}
